);

counterexample:
INSERT INTO t1 (c1, c2) VALUES ('beerA', 'x');
INSERT INTO t2 (c1, c2) VALUES ('Corona', 'b1');
INSERT INTO t2 (c1, c2) VALUES ('Amstel', 'b2');
INSERT INTO t3 (c1, c2) VALUES ('user1', 'u1');
INSERT INTO t3 (c1, c2) VALUES ('user2', 'u2');

-- t5 row makes Q1 return 'beerA'
INSERT INTO t5 (c1, c2, c3) VALUES ('beerA', 'Corona', 3.50);

-- Link user1 to beerA so Q2 returns 'user1'
INSERT INTO t4 (c1, c2, c3) VALUES ('user1', 'beerA', 1);

-- t6 row ensures NOT IN can exclude someone else (not user1)
INSERT INTO t6 (c1, c2) VALUES ('user2', 'Corona');

