counterexample:
INSERT INTO t1 (c1, c2) VALUES ('a', 'x');
INSERT INTO t2 (c1, c2) VALUES ('Corona', 'x'), ('Flu', 'y');
INSERT INTO t3 (c1, c2) VALUES ('u', 'x');

-- t4 row: c1='u', c2='a', c3=1
INSERT INTO t4 (c1, c2, c3) VALUES ('u', 'a', 1);

-- t5 row: c1='a', c2='Corona', c3=2.00 (note: c1 != t4.c1 and c3 differs)
INSERT INTO t5 (c1, c2, c3) VALUES ('a', 'Corona', 2.00);

-- t6 row: same c1 as t4, but c2 is not 'Corona'
INSERT INTO t6 (c1, c2) VALUES ('u', 'Flu');

